import {read,put} from './project-store.js';
export const jobEvent=(status,title,message='',id=crypto.randomUUID())=>window.dispatchEvent(new CustomEvent('vmet:job',{detail:{id,status,title,message}}));
export function mountNotifications(){const button=document.createElement('button');button.type='button';button.className='notification-toggle';button.setAttribute('aria-label','Уведомления');button.innerHTML='<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg><span hidden></span>';document.querySelector('#export-open').before(button);const d=document.createElement('dialog');d.className='notification-center editor-control-dialog';d.innerHTML='<div class="control-heading"><h2>Уведомления</h2><button type="button" aria-label="Закрыть уведомления">×</button></div><p>Завершение монтажа, распознавания и экспорта. Для фоновых задач оставьте вкладку открытой.</p><button type="button" class="enable-notifications">Включить системные уведомления</button><p class="notification-permission" role="status"></p><div class="notification-list" role="log"></div>';document.body.append(d);let items=[],unread=0;const title=document.title;function render(){button.querySelector('span').hidden=!unread;button.querySelector('span').textContent=String(unread);const list=d.querySelector('.notification-list');list.replaceChildren();for(const n of items.slice().reverse()){const row=document.createElement('article'),h=document.createElement('strong'),p=document.createElement('p'),time=document.createElement('small');h.textContent=n.title;p.textContent=n.message;time.textContent=new Date(n.time).toLocaleTimeString();row.dataset.status=n.status;row.append(h,p,time);list.append(row)}if(!items.length)list.textContent='Пока нет событий.'}button.onclick=()=>{unread=0;document.title=title;render();d.showModal()};d.querySelector('[aria-label="Закрыть уведомления"]').onclick=()=>d.close();d.querySelector('.enable-notifications').onclick=async()=>{const status=d.querySelector('.notification-permission');if(!('Notification'in window)){status.textContent='Браузер показывает только уведомления внутри сайта.';return}const p=await Notification.requestPermission();status.textContent=p==='granted'?'Готово: уведомим, когда задача завершится в фоне.':p==='denied'?'Уведомления заблокированы в настройках браузера. События останутся здесь.':'Разрешение не выдано. События останутся здесь.'};read('job-notifications').then(v=>{items=Array.isArray(v)?v.slice(-40):[];render()});window.addEventListener('vmet:job',({detail})=>{if(!['done','error','running'].includes(detail?.status))return;const n={id:String(detail.id).slice(0,100),title:String(detail.title).slice(0,140),message:String(detail.message||'').slice(0,500),status:detail.status,time:Date.now()},at=items.findIndex(x=>x.id===n.id);if(at<0)items.push(n);else items[at]=n;items=items.slice(-40);put('job-notifications',items).catch(()=>{});if(n.status!=='running'){unread++;if(document.hidden){document.title=`(${unread}) ${title}`;if('Notification'in window&&Notification.permission==='granted'){try{const notification=new Notification(n.title,{body:n.message,icon:'/favicon.ico',tag:n.id});notification.onclick=()=>{window.focus();notification.close()}}catch{}}}}render()});window.addEventListener('focus',()=>{document.title=title});return {button};}
